<span id="CrossTest"></span>



<script>

// Replace old docCookies with localStorage proxy (with fallback)

var docCookies = new ( function() {

    var data = {};

    var useLocalStorage = typeof window.localStorage !== 'undefined';

 

    this.getItem = function( key ) {

        if ( useLocalStorage ) {

            return localStorage.getItem( key );

        }

 

        if ( typeof data[ key ] === 'undefined' ) {

            return null;

        }

 

        return data[ key ];

    };

 

    this.setItem = function( key, value ) {

        if ( useLocalStorage ) {

            localStorage.setItem( key, value );

        } else {

            data[ key ] = value;

        }

    };

 

    this.removeItem = function( key, value ) {

        if ( useLocalStorage ) {

            localStorage.removeItem( key );

        } else {

            delete data[ key ];

        }

    };

 

    this.hasItem = function( key ) {

        var result = this.getItem( key );

 

        return result !== null || typeof result === 'undefined';

    };

} );



String.prototype.hashCode = function(){

    var hash = 0;

    if (this.length == 0) return hash;

    for (i = 0; i < this.length; i++) {

    	char = this.charCodeAt(i);

    	hash = ((hash<<5)-hash)+char;

    	hash = hash & hash; // Convert to 32bit integer

    }

    return hash;

}





$("#button").click(function (){

    docCookies.setItem("numSolved", 0);

    docCookies.removeItem("image");

    docCookies.removeItem("class");

    docCookies.removeItem("containment");

    docCookies.removeItem("interview");

    docCookies.removeItem("cross");

    updateText();

});



var mostInstructions = '<p style="text-align: center; color: red"><b>Security Warning</b></p><p>Automated systems have detected substantial amounts of database corruption in this document. To ensure no hazardous or inaccurate content is shown, affected sections have been redacted in full.</p><p>Links to last-known secure copies are provided. Congruent with Protocol C-Gobekli, a decryption password may be extracted from each of these archival documents, and entered in the security field below to restore the corresponding damaged section of this page. In accordance with password best practice, each of these will be a single English word.</p>'

var finalInstructions = '<p style="text-align: center; font-size: 200%;"><span style="color:red">5</span>, <span style="color:magenta">2</span>, <span style="color:blue">4</span>, <span style="color:green">7</span>, <span style="color:orange">1</span></p>'

function adjustOverview(){

    var numSolved = parseInt(docCookies.getItem("numSolved"));

    var solStrings = [mostInstructions,

                      mostInstructions,

                      mostInstructions,

                      mostInstructions,

                      mostInstructions,

                      finalInstructions];

    $("#Instructions").html(solStrings[numSolved]);

}



var imagePuzzleUnsolved = '<div class="scp-image-block block-right"style="width:300px"><div style="background:#640000;height:300px"></div><div class="scp-image-caption"><p><a href="https://scp-wiki.wikidot.com/2212-archival-image"target="_blank">[MASSIVE DATABASE CORRUPTION]</a></p></div></div>';

